// STAR 2 sketch: abort in-flight search so “s” cannot overwrite “sql”
let generation = 0
async function search(q: string, signal: AbortSignal) {
  const mine = ++generation
  const res = await fetch(`/api/search?q=${q}`, { signal })
  if (mine !== generation) return // late response must not win
  return res.json()
}
// Verify: Network waterfall + server QPS, not “it feels snappier”
// STAR 1 verify: Performance panel long tasks on scroll + INP attribution

