import { onCLS, onINP, onLCP } from 'web-vitals'
function send(metric: { name: string; value: number; id: string }) {
  navigator.sendBeacon('/rum', JSON.stringify(metric))
}
onLCP(send, { reportAllChanges: false }) // good ≤ 2500 ms
onINP(send, { reportAllChanges: false }) // good ≤ 200 ms; replaced FID
onCLS(send) // good ≤ 0.1
